// ---------- fusion dans MINERAUX (fiches modales unifiées) ----------
for (const fam of OXYDES) {
  for (const m of fam.especes) {
    const famNom = { fer: "de fer", manganese: "de manganèse", aluminium: "d'aluminium", titane: "de titane",
      cuivre: "de cuivre", zinc: "de zinc", chrome: "de chrome", magnesium: "de magnésium", etain: "d'étain",
      zirconium: "de zirconium", uranium: "d'uranium/thorium", niobium: "de niobium/tantale" }[fam.id];
    const base = {
      nom: m.nom, formule: m.formule,
      famille: (m.formule.includes("OH") ? "Oxy-hydroxyde " : "Oxyde ") + famNom,
      durete: m.durete, densite: m.densite, stabilite: m.stabilite, swatch: m.swatch,
      devient: m.devient, note: m.note, clivage: m.clivage, eclat: m.eclat,
      systeme: m.systeme, couleurs: m.couleurs, contexte: m.contexte, oxydeDe: fam.id,
    };
    // les minéraux déjà décrits (goethite, hématite…) gardent leur prose d'origine
    MINERAUX[m.id] = Object.assign(base, MINERAUX[m.id] || {});
    Object.assign(MINERAUX[m.id], { systeme: m.systeme, couleurs: m.couleurs, contexte: m.contexte, oxydeDe: fam.id });
  }
}

